'use strict';
/* Leveled books Grades 4–5 (original). Appended to LEVELED_BOOKS by leveled.js. */
const BOOKS_45 = [
  {id: "g4-lemon-promise", band: "4", lvl: 2, series: "Pip's Neighborhood", title: "The Lemon Tree Promise", cover: "🍋", bg: "farm", kind: "fiction",
    vocab: [["shriveled","dried up and wrinkled"], ["drooping","hanging down in a weak, tired way"], ["recovered","got healthy and strong again"], ["exhausted","very, very tired"], ["heroism","great bravery"]],
    pages: [
      {icon: "🍋", text: "Mateo Ramirez loved the lemon tree in his grandmother's backyard in Sacramento. Every summer, Abuela squeezed its fruit into a big pitcher of lemonade for the whole street. This year, though, she was flying to Mexico to visit her sister for three weeks. \"Will you take care of my tree while I am gone?\" she asked. Mateo promised he would water it every other day, and his friend Pip, a cheerful little chick, promised to help."},
      {icon: "⚽", text: "The first few days went smoothly. Mateo filled the green watering can each morning, and Pip hopped along the edge of the soil, checking that every root got a drink. Then summer soccer camp began. Mateo came home sweaty and tired, and the watering can sat by the fence, forgotten. \"I will water it tomorrow,\" he told Pip, waving his hand as if the tree could wait forever."},
      {icon: "☀️", text: "A heat wave rolled over the valley like a heavy blanket. For four days the temperature climbed past one hundred degrees. When Pip finally peeked into the backyard, he gasped. The lemon tree's leaves were curled and drooping, and three small green lemons lay shriveled on the ground. Pip raced to find Mateo, flapping his tiny wings so fast they were a blur."},
      {icon: "😟", text: "Mateo stared at the tree, and his stomach sank. He remembered Abuela's hands as she patted the trunk and called it her old friend. \"This is my fault,\" he whispered. He wanted to hide the fallen lemons so no one would know. Pip tilted his head. \"Hiding them will not help the tree,\" he said gently. \"What does the tree need right now?\""},
      {icon: "💧", text: "Mateo took a deep breath and decided to fix his mistake instead of hiding it. He watered the tree slowly and deeply, so the water soaked down to the roots instead of running away. He spread a thick layer of wood chips around the trunk to keep the soil cool and damp. Then he made a chart and taped it to the refrigerator, with a box to check after every watering."},
      {icon: "🌱", text: "Day by day, the tree recovered. The curled leaves flattened out and turned a shiny green again, and tiny white blossoms appeared on the branches. Mateo never skipped a box on his chart, even on days when camp left him exhausted. He discovered that taking care of something was not one big act of heroism. It was a hundred small, ordinary choices, made again and again."},
      {icon: "🍹", text: "When Abuela came home, Mateo showed her the chart and told her the whole truth about the heat wave and the shriveled lemons. She listened quietly, then hugged him tight. \"Anyone can make a mistake,\" she said. \"A person who keeps a promise after breaking it is someone I can trust.\" That evening, the street gathered for lemonade, and Mateo proudly poured the very first glass."}],
    questions: [
      {q: "Why did Mateo stop watering the lemon tree?", a: "He was busy and tired from soccer camp", wrong: ["Abuela told him to stop", "It rained every day"], type: "detail", mid: true},
      {q: "Why did Mateo want to hide the fallen lemons at first?", a: "He felt ashamed that the tree was hurt because of him", wrong: ["He wanted to plant them as seeds", "He planned to sell them to neighbors"], type: "inference", evidence: "\"This is my fault,\" he whispered."},
      {q: "How does Mateo change from the middle of the story to the end?", a: "He goes from forgetting his promise to keeping it every day", wrong: ["He goes from loving the tree to disliking it", "He goes from working hard to giving up"], type: "character", evidence: "Mateo never skipped a box on his chart, even on days when camp left him exhausted."},
      {q: "\"A heat wave rolled over the valley like a heavy blanket.\" What does this simile tell you?", a: "The heat felt thick and hard to escape", wrong: ["The weather turned cold and cozy", "A real blanket blew across the valley"], type: "vocabulary"},
      {q: "What is the theme of this story?", a: "Owning up to a mistake and fixing it builds trust", wrong: ["Lemon trees grow best in cold places", "Soccer is more important than chores"], type: "theme", evidence: "\"A person who keeps a promise after breaking it is someone I can trust.\""},
      {q: "What did Mateo do differently after the heat wave than before it?", a: "He used a chart so he would not forget to water", wrong: ["He let Pip do all the watering", "He watered only when it rained"], type: "compare"}]},
  {id: "g4-salmon-journey", band: "4", lvl: 3, series: "Pip Explores California", title: "The Long Journey of a Salmon", cover: "🐟", bg: "sea", kind: "informational",
    vocab: [["estuary","a place where a river meets the sea and fresh and salt water mix"], ["current","water moving in one direction"], ["upstream","toward the start of a river, against the flow"], ["remarkable","amazing and worth noticing"], ["hatcheries","places where people raise baby fish"]],
    pages: [
      {heading: "A Fish with Two Homes", icon: "🐟", text: "Chinook salmon live in two very different places during their lives. They begin and end in cold, fresh rivers, such as the Sacramento River in Northern California. In between, they spend years in the salty Pacific Ocean. Few animals make such a long and difficult journey. Following one salmon from start to finish shows how each stage of its life depends on the one before it."},
      {heading: "Life Begins in the Gravel", icon: "🥚", text: "The journey starts in autumn, when a female salmon digs a nest in the gravel of a cool, clear stream. She lays thousands of tiny orange eggs, and a male fertilizes them. The gravel protects the eggs, and the moving water carries oxygen to them. After a few months, the eggs hatch into small fish called alevins, which hide among the stones and feed on a yolk sac attached to their bellies."},
      {heading: "Growing Up in the River", icon: "🌿", text: "Once the yolk is gone, the young fish swim out to hunt for insects. Now they are called fry. They stay close to the riverbanks, where plants and fallen logs give them shade and places to hide from hungry birds. As they grow, their bodies slowly change so they will be able to survive in salt water. This change is one of the most remarkable parts of their lives."},
      {heading: "Out to Sea", icon: "🌊", text: "When the young salmon are a few inches long, they let the current carry them downstream. They pass through the wide estuary where the river meets San Francisco Bay, a place where fresh and salt water mix. Then they swim out into the open ocean. For the next two to five years, they feast on shrimp and small fish and grow large and strong."},
      {heading: "The Journey Home", icon: "🧭", text: "Finally, something signals the adult salmon that it is time to return. Scientists believe salmon use the Earth's magnetic field to find the right stretch of coast and then use their powerful sense of smell to find their home stream. Swimming upstream is exhausting work. The fish leap over rocks and push against strong currents, and they stop eating completely during the trip."},
      {heading: "Why Salmon Need Help", icon: "🚧", text: "Today, many salmon cannot finish this journey. Dams block some rivers, so the fish cannot reach the cool streams where they were born. During droughts, rivers become too warm and shallow for eggs to survive. As a result, the number of salmon in California has dropped sharply over the past century. Because so many other animals eat salmon, this loss affects bears, eagles and even orcas."},
      {heading: "Helping Salmon Return", icon: "🛠️", text: "People are working to solve these problems. Some communities have removed old dams or built fish ladders, which are like staircases of water that let salmon climb past. Volunteers plant trees along riverbanks to shade the water and keep it cool. Hatcheries raise young salmon and release them into rivers. Each small step helps more salmon complete the long journey home."}],
    questions: [
      {q: "Where do salmon eggs develop?", a: "In nests in the gravel of cool streams", wrong: ["Floating in the open ocean", "In the salty water of San Francisco Bay"], type: "detail", mid: true},
      {q: "What is the main idea of this book?", a: "Salmon make a long journey between rivers and the ocean, and people can help them finish it", wrong: ["Salmon spend their whole lives in one small pond", "Bears are the only danger salmon face"], type: "main idea"},
      {q: "How is most of this book organized?", a: "In time order, following the stages of a salmon's life", wrong: ["As a list of different kinds of fish", "As an argument for and against eating fish"], type: "text feature"},
      {q: "Why might removing a dam also help orcas?", a: "More salmon could reach their streams, so orcas would have more food", wrong: ["Orcas could swim up the river to new homes", "Dams make the ocean water too cold for orcas"], type: "inference", evidence: "Because so many other animals eat salmon, this loss affects bears, eagles and even orcas."},
      {q: "What does \"estuary\" mean in this book?", a: "A place where river water and seawater mix", wrong: ["A nest made of gravel", "A staircase of water for fish"], type: "vocabulary"},
      {q: "Why does the author describe fish ladders, tree planting and hatcheries?", a: "To show ways people are solving the salmon's problems", wrong: ["To explain how salmon find their home stream", "To describe what salmon eat in the ocean"], type: "author purpose", evidence: "People are working to solve these problems."}]},
  {id: "g4-kite-contest", band: "4", lvl: 4, series: "Friends and Neighbors", title: "The Kite Contest", cover: "🪁", bg: "sky", kind: "fiction",
    vocab: [["gusty","with sudden strong bursts of wind"], ["unpredictable","hard to know what will happen next"], ["triumphant","proud and happy after a success"], ["admitted","said something was true, even though it was hard"], ["combined","put together into one"]],
    pages: [
      {icon: "🪁", text: "Amani Mwangi had lived in San Diego for only two months, and most days he still felt like a puzzle piece in the wrong box. Back in Nairobi, his grandfather had taught him to build kites from thin sticks, string and old plastic bags. When Amani saw a poster for the spring kite festival at the beach, his heart leaped. Here, at last, was something he knew how to do."},
      {icon: "🤝", text: "Then his teacher, Miss Lopez, announced that students would enter the festival in pairs. She placed Amani with Kenji Sato, a boy who talked constantly and laughed loudly. Kenji had already chosen a design: a huge dragon kite with a long, glittering tail. Amani frowned. He was certain his grandfather's simple diamond kite would fly higher than any dragon. Neither boy wanted to give up his own idea."},
      {icon: "😤", text: "For a week, they argued during every recess. Kenji said Amani's kite looked plain and boring. Amani said Kenji's dragon was far too heavy to leave the ground. Finally, they agreed to build both kites and test them at the park on Saturday. Amani secretly hoped the dragon would crash, so Kenji would have to admit he had been wrong all along."},
      {icon: "🌬️", text: "On Saturday the wind was gusty and unpredictable. Kenji's dragon lifted briefly, wobbled, and then flopped onto the grass like a tired fish. Amani's diamond kite shot upward, and for a moment he felt triumphant. But a sudden gust yanked the kite sideways, the thin plastic split down the middle, and it spun into a tree. Both boys stood silently, holding empty strings."},
      {icon: "🔧", text: "Kenji climbed the tree and carefully untangled the torn diamond. As he handed it back, he said quietly, \"Your frame is really strong. My kite is just too heavy.\" Amani looked at the dragon's tough, shiny fabric. \"And your material does not rip,\" he admitted. Slowly, an idea began to take shape between them, like a kite rising on a gentle breeze."},
      {icon: "✂️", text: "The next week, the boys worked side by side. Amani showed Kenji how to bind the sticks tightly with string, the way his grandfather had taught him. Kenji cut a light diamond from leftover dragon fabric and painted a small dragon in the center. They kept the glittering tail, but trimmed it so it would not drag the kite down. The new kite combined the best of both designs."},
      {icon: "🏆", text: "On festival day, their kite climbed steadily above the waves and stayed there, even when the wind gusted. They did not win the prize for the highest kite, but the judges gave them a ribbon for the most creative design. Walking home, Kenji asked Amani to teach him more about kites from Kenya. For the first time since moving, Amani felt that the puzzle piece had found its place."}],
    questions: [
      {q: "Why did Amani and Kenji argue at first?", a: "Each boy wanted to use his own kite design", wrong: ["They both wanted a different partner", "Kenji broke Amani's kite on purpose"], type: "detail", mid: true},
      {q: "Amani \"felt like a puzzle piece in the wrong box.\" What does this mean?", a: "He felt like he did not fit in", wrong: ["He was very good at puzzles", "He had lost something important"], type: "vocabulary"},
      {q: "How does Amani change during the story?", a: "He goes from wanting to prove Kenji wrong to valuing Kenji's ideas", wrong: ["He goes from loving kites to not caring about them", "He goes from being friendly to being lonely"], type: "character", evidence: "\"And your material does not rip,\" he admitted."},
      {q: "How were the two first kites different?", a: "The diamond kite was strong but tore, and the dragon was tough but too heavy", wrong: ["The diamond kite was heavy, and the dragon was light", "Both kites flew perfectly in the wind"], type: "compare"},
      {q: "What is the theme of this story?", a: "Working together can create something better than working alone", wrong: ["The biggest kite always wins", "It is best to keep your ideas to yourself"], type: "theme", evidence: "The new kite combined the best of both designs."},
      {q: "Why does the author include the test day at the park?", a: "To show each kite's problem, which leads the boys to work together", wrong: ["To explain how parks are built", "To prove that Kenji is the better kite builder"], type: "author purpose"}]},
  {id: "g4-sun-wind", band: "4", lvl: 5, series: "Big Ideas", title: "Power from the Sun and the Wind", cover: "☀️", bg: "sky", kind: "informational",
    vocab: [["renewable","able to be replaced by nature, so it will not run out"], ["turbines","machines with blades that spin to make power"], ["generator","a machine that makes electricity"], ["enormous","very, very big"], ["pollute","to make air, water or land dirty"]],
    pages: [
      {heading: "A Big Problem", icon: "🏭", text: "For more than a century, most of the electricity in the United States came from burning coal, oil and natural gas. These fuels work well, but burning them releases gases that trap heat in the air and warm the planet. They also pollute the air people breathe. In addition, these fuels will eventually run out. Engineers have been searching for cleaner sources of energy that will never be used up."},
      {heading: "Energy from Sunlight", icon: "☀️", text: "Solar panels turn sunlight directly into electricity. Each panel contains special materials that release a tiny flow of electric current when light strikes them. Panels can sit on the roof of a single house or cover acres of desert in huge solar farms. California, with its long, sunny days, now produces more solar power than almost any other state in the country."},
      {heading: "Energy from Moving Air", icon: "🌬️", text: "Wind turbines capture the energy of moving air. When the wind blows, it pushes against the long blades and spins them like a giant pinwheel. The spinning blades turn a machine called a generator, which produces electricity. Turbines work best in open places where strong winds blow often, such as mountain passes, wide plains and even far out at sea."},
      {heading: "How They Are Alike", icon: "⚖️", text: "Solar and wind power have a lot in common. Both are renewable, which means the sun and wind will not run out. Neither one burns fuel, so neither releases smoke or harmful gases while making electricity. Both have also become much cheaper over the past twenty years, so more cities, schools and families can afford them."},
      {heading: "How They Are Different", icon: "🔀", text: "The two sources also differ in important ways. Solar panels produce power only during the day, and they make less on cloudy days. Wind turbines can spin day or night, but only when the wind is blowing. Solar panels are silent and can fit on small rooftops, while turbines are enormous and need lots of open space. Some neighbors complain that turbines are noisy or spoil the view."},
      {heading: "Solving the Gaps", icon: "🔋", text: "Because neither the sun nor the wind is available all the time, engineers have developed solutions. Giant batteries store extra electricity when the sun is bright, then release it after sunset. Power companies also combine solar and wind, since breezes often grow stronger in the evening just as sunlight fades. Together, the two sources can fill in each other's gaps."},
      {heading: "Looking Ahead", icon: "🌍", text: "California has set a goal of getting all of its electricity from clean sources by the year two thousand forty five. Reaching that goal will require more panels, more turbines and better ways to store energy. It will also require people to use electricity wisely. Turning off lights and unplugging chargers may seem small, but millions of small actions add up to a brighter future."}],
    questions: [
      {q: "How does a wind turbine make electricity?", a: "Wind spins the blades, which turn a generator", wrong: ["Sunlight strikes special materials in the blades", "It burns a small amount of fuel"], type: "detail", mid: true},
      {q: "What is the main idea of this book?", a: "Solar and wind are clean energy sources with different strengths that work well together", wrong: ["Coal is the best way to make electricity", "Wind turbines are too noisy to be useful"], type: "main idea"},
      {q: "How are solar power and wind power alike?", a: "Neither one burns fuel or releases harmful gases", wrong: ["Both work only during the day", "Both need lots of open space"], type: "compare", evidence: "Neither one burns fuel, so neither releases smoke or harmful gases while making electricity."},
      {q: "Which sentence tells a difference between the two sources?", a: "Turbines can work at night if it is windy, but solar panels need sunlight", wrong: ["Solar panels are noisier than turbines", "Turbines fit easily on small rooftops"], type: "compare", evidence: "Wind turbines can spin day or night, but only when the wind is blowing."},
      {q: "How is the section \"Solving the Gaps\" organized?", a: "It describes a problem and then explains solutions", wrong: ["It tells a story in time order", "It lists the parts of a solar panel"], type: "text feature"},
      {q: "What does \"renewable\" mean in this book?", a: "Able to be replaced by nature so it will not run out", wrong: ["Very expensive to build", "Harmful to the air"], type: "vocabulary"}]},
  {id: "g4-lighthouse-mystery", band: "4", lvl: 6, series: "Pip's Mystery Club", title: "The Mystery of the Glowing Lighthouse", cover: "🌙", bg: "sea", kind: "fiction",
    vocab: [["rumor","a story people pass around that may not be true"], ["suspected","thought someone might be guilty without proof"], ["magnify","to make something look bigger or brighter"], ["evidence","facts or clues that show what is true"], ["dusk","the time just after sunset when it grows dark"]],
    pages: [
      {icon: "🌙", text: "Everyone in the little coastal town of Seal Cove knew the old lighthouse had been closed for years. So when Diego Reyes looked out his bedroom window one foggy night and saw a soft green glow at the top of the tower, he nearly fell off his bed. By breakfast, the rumor had spread through the whole neighborhood. Some kids whispered that the lighthouse was haunted by the ghost of a lost sailor."},
      {icon: "🔍", text: "Diego's older sister, Sofia, did not believe in ghosts, but she did believe in mysteries. She opened her notebook to a fresh page and wrote three questions. When does the glow appear? What color is it? Who can get inside the tower? Her friend Pip, a curious little chick, perched on her shoulder. \"A good detective collects clues before deciding anything,\" Pip reminded her. Sofia nodded, although she already suspected the museum keeper."},
      {icon: "🧓", text: "The museum keeper, Walter Kim, was a retired fisherman who held the only key to the lamp room. He was grumpy about visitors and had been seen carrying boxes up the hill. \"He must be sneaking up there at night,\" Sofia told Pip. \"Maybe he wants to scare people away so no one will bother him.\" Pip ruffled his feathers. \"That is a guess,\" he said, \"not a clue.\""},
      {icon: "📓", text: "That night, Sofia and Diego watched from their porch with a flashlight and a notebook. The green glow appeared just after dusk, grew brighter, and then slowly faded around midnight. Sofia wrote down every detail. Strangely, no car drove up the hill, and no one walked along the path. The tower door stayed locked, and Walter's house beside it stayed completely dark."},
      {icon: "🌼", text: "The next afternoon, Sofia and Pip hiked up to the lighthouse to look for more clues. In the garden at the base of the tower, they found a row of brand new garden lights with small solar panels on top. Walter was watering the flowers nearby. \"Put those in last week,\" he grumbled. \"The garden club asked me to brighten up the place. I even set one on the lamp room balcony.\""},
      {icon: "💡", text: "Sofia's mind raced as the clues clicked together like links in a chain. The solar lights soaked up sunshine all day and switched on by themselves at dusk. Their covers were green, and the one on the balcony sat right beside the giant glass lens, which was built to magnify a small light so ships could see it for miles. As each battery ran low, the glow faded. The ghost was simply a garden light shining through the lens."},
      {icon: "😊", text: "Sofia felt her cheeks grow warm. She had been so sure Walter was guilty that she had almost ignored the real evidence. She walked back to the garden and apologized for suspecting him. To her surprise, Walter chuckled. \"Folks have called me grumpy for years, and they were right,\" he said. Then he offered Sofia and Diego a tour of the lamp room, the first visitors he had invited inside in years."},
      {icon: "📰", text: "On Saturday, Sofia explained the mystery to the whole town at the museum, with Walter standing proudly beside her. The garden club decided to keep the balcony light, and now the old lighthouse glows green every evening. Sofia added one more line to her notebook, under her three questions. It said, \"Follow the clues, not your guesses.\" Pip thought it was the best clue of all."}],
    questions: [
      {q: "Why did Sofia first think Walter was causing the glow?", a: "He had the only key and seemed grumpy about visitors", wrong: ["She saw him climbing the tower at night", "Diego told her Walter was a ghost"], type: "detail", mid: true},
      {q: "Why was it important that no one walked up the path at night?", a: "It showed that no person was turning on the light", wrong: ["It proved the lighthouse was haunted", "It meant Walter was hiding inside the tower"], type: "inference", evidence: "Strangely, no car drove up the hill, and no one walked along the path."},
      {q: "Why did the green glow fade around midnight?", a: "The solar batteries ran low", wrong: ["Walter turned the light off", "The fog blocked it completely"], type: "detail"},
      {q: "How does Sofia change by the end of the story?", a: "She learns to trust evidence instead of jumping to conclusions", wrong: ["She stops liking mysteries", "She decides that ghosts are real"], type: "character", evidence: "She had been so sure Walter was guilty that she had almost ignored the real evidence."},
      {q: "What is the theme of this mystery?", a: "Look carefully at the facts before you blame someone", wrong: ["Old buildings are always haunted", "Grumpy people cannot be trusted"], type: "theme"},
      {q: "\"The clues clicked together like links in a chain.\" What does this mean?", a: "The clues suddenly connected and made sense", wrong: ["Sofia found a real chain in the garden", "The clues got lost and mixed up"], type: "vocabulary"}]},
  {id: "g5-heritage-song", band: "5", lvl: 1, series: "Voices", title: "The Song I Almost Didn't Sing", cover: "🎤", bg: "party", kind: "fiction",
    vocab: [["heritage","traditions and history passed down in a family or culture"], ["melody","the tune of a song"], ["memorizing","learning something so you can remember it exactly"], ["applause","clapping to show you liked something"], ["courage","being brave even when you are scared"]],
    pages: [
      {icon: "🎤", text: "My name is Selam, and until last spring, my voice lived mostly inside my head. In class I knew the answers. Whenever I raised my hand, though, my words seemed to shrink and hide behind my teeth. So when my teacher announced that our school in Oakland would hold a Family Heritage Night, and that each of us would share something from our culture, my heart dropped into my shoes like a stone."},
      {icon: "🏠", text: "That evening, I told my grandmother about the assignment. She lives with us, and she came from Ethiopia when my mother was a baby. Without a word, she began to hum a song she used to sing while roasting coffee beans in Addis Ababa. Then she sang the words softly in Amharic. The melody rose and fell like hills I had only seen in photographs. \"Sing this,\" she said. \"It belongs to you, too.\""},
      {icon: "😰", text: "I wanted to say no. Everyone else had easy plans. Marcus was bringing his family's famous gumbo, and Priya was showing photographs of a festival in India. Nobody else had to stand alone on a stage and open their mouth. What if my voice cracked? What if the other kids laughed at words they did not understand? Each question piled onto the last until it felt like a mountain I could never climb."},
      {icon: "📅", text: "Still, every night for three weeks, Grandmother and I practiced in the kitchen. She taught me what each line meant: the song was about a mother waiting for her children to come home across the mountains. Slowly, the strange sounds became words, and the words became pictures. I began to understand that I was not just memorizing a song. I was carrying a piece of my family's story."},
      {icon: "🎭", text: "On Heritage Night, the cafeteria was packed with families, folding chairs and the smell of a dozen different dinners. When my teacher called my name, my knees turned to jelly. I walked to the front, gripping the microphone so tightly my fingers ached. For a long moment, I could not make a sound. Then I found my grandmother's face in the third row. She nodded once, slowly, the way she did in the kitchen."},
      {icon: "🎶", text: "I closed my eyes and began. My first notes wobbled like a newborn calf, but then something shifted. I was not in the cafeteria anymore; I was in our kitchen, with the smell of roasted coffee and Grandmother's quiet hum beside me. My voice grew steadier and stronger with every line. By the end of the song, I was no longer singing to an audience. I was singing to her."},
      {icon: "👏", text: "When I opened my eyes, the room was silent. For one terrible second, I thought I had made a huge mistake. Then the applause rolled toward me like a wave. Afterward, a boy named Luis told me that his own grandfather sang old songs in Spanish that Luis had never learned. \"Maybe I should ask him to teach me,\" he said. I realized my song had opened a door for someone else."},
      {icon: "🌅", text: "I still do not raise my hand in every class. Courage, I have learned, is not the same as never being afraid. It is being afraid and choosing to sing anyway. Now, when my words try to hide behind my teeth, I think about that night. I remember that my voice carries more than sound. It carries the people who taught me, and that makes it worth hearing."}],
    questions: [
      {q: "Why did Selam feel nervous about Heritage Night?", a: "She was shy and afraid to sing alone in front of people", wrong: ["She did not have anything to share", "Her grandmother could not come"], type: "character", mid: true},
      {q: "From whose point of view is this story told?", a: "Selam's, in first person", wrong: ["Her grandmother's, in first person", "A narrator outside the story, in third person"], type: "point of view"},
      {q: "\"My heart dropped into my shoes like a stone.\" What does this simile show?", a: "Selam suddenly felt scared and worried", wrong: ["Selam tripped and fell down", "Selam felt calm and happy"], type: "vocabulary"},
      {q: "Why did seeing her grandmother help Selam begin to sing?", a: "It reminded her of practicing calmly together in the kitchen", wrong: ["Her grandmother was about to sing instead", "She wanted to check that her grandmother was awake"], type: "inference", evidence: "She nodded once, slowly, the way she did in the kitchen."},
      {q: "How does Selam change from the beginning of the story to the end?", a: "She goes from hiding her voice to believing it is worth hearing", wrong: ["She goes from loving music to disliking it", "She goes from feeling brave to feeling more afraid"], type: "character", evidence: "I remember that my voice carries more than sound."},
      {q: "What is the theme of this story?", a: "Courage means feeling afraid and acting anyway", wrong: ["Only people who are never afraid can perform", "Food is the only way to share a culture"], type: "theme", evidence: "It is being afraid and choosing to sing anyway."},
      {q: "How was Selam's plan different from Marcus's and Priya's plans?", a: "She had to perform alone on stage, while they shared food and photographs", wrong: ["She brought food, while they sang songs", "They had to perform, while she only showed pictures"], type: "compare"}]},
  {id: "g5-california-water", band: "5", lvl: 2, series: "Big Ideas", title: "Where California's Water Comes From", cover: "💧", bg: "rain", kind: "informational",
    vocab: [["evaporates","turns from a liquid into a gas"], ["condenses","turns from a gas into a liquid"], ["precipitation","water that falls from clouds as rain, snow, sleet or hail"], ["drought","a long time with much less rain than usual"], ["conserve","to use something carefully so it is not wasted"], ["aquifers","layers of rock and soil underground that hold water"]],
    pages: [
      {heading: "Water on the Move", icon: "💧", text: "Every drop of water on Earth is part of an endless journey called the water cycle. The sun heats oceans, lakes and rivers, and some of that water evaporates, rising into the air as an invisible gas called water vapor. As the vapor rises, it cools and condenses into tiny droplets that form clouds. When the droplets grow heavy enough, they fall back to Earth as precipitation: rain, snow, sleet or hail."},
      {heading: "A Frozen Reservoir", icon: "🏔️", text: "In California, the water cycle has an unusual feature. Most of the state's rain and snow falls during a few winter months, especially in the Sierra Nevada mountains. There, snow piles up in a thick layer called the snowpack. In spring and summer, the snowpack melts slowly and feeds rivers that flow down to farms and cities. Because it stores water for months, people often call the snowpack a frozen reservoir."},
      {heading: "Moving Water to People", icon: "🚰", text: "The problem is that most rain and snow fall in the north and in the mountains, while most people live in the south and along the coast. To solve this, Californians built one of the largest water systems in the world. Dams hold water in reservoirs, and hundreds of miles of canals and pipelines carry it to farms in the Central Valley and to cities such as Los Angeles and San Diego. Moving all that water takes a huge amount of energy and careful planning."},
      {heading: "When the Rain Stops", icon: "☀️", text: "A drought is a long period with much less rain and snow than usual. California has always had droughts, but some recent ones have been severe. From two thousand twelve to two thousand sixteen, the state suffered one of the driest stretches in its recorded history. In the spring of two thousand fifteen, the snowpack was only about five percent of its normal size. Reservoirs shrank, and some wells ran completely dry."},
      {heading: "Ripple Effects", icon: "🌾", text: "A drought affects far more than lawns and gardens. Farmers may leave fields unplanted, which means less food and fewer jobs. Rivers grow warm and shallow, which harms fish such as salmon. Dry forests burn more easily, so wildfires can spread faster and farther. Even the ground can sink, because when people pump too much water from underground, the soil above it collapses like a squeezed sponge."},
      {heading: "Saving Every Drop", icon: "🚿", text: "During the last major drought, Californians found creative ways to conserve water. Many families replaced thirsty lawns with native plants that need little watering. Cities fixed leaky pipes and paid people to install toilets and showerheads that use less water. Some farms switched to drip irrigation, which delivers small amounts of water directly to each plant's roots instead of spraying whole fields. Together, these changes saved enormous amounts of water."},
      {heading: "Planning for the Future", icon: "🌧️", text: "Scientists predict that as the climate warms, more precipitation will fall as rain instead of snow, and the snowpack will melt earlier in the year. That means the frozen reservoir will hold less water for summer. To prepare, communities are capturing storm water, cleaning and reusing wastewater, and refilling underground aquifers during wet years. Every drop saved today helps the state survive the next dry spell."},
      {heading: "Your Part in the Cycle", icon: "🧒", text: "Students can help, too. Turning off the faucet while brushing your teeth can save several gallons of water each day. Shorter showers, full loads of laundry and telling an adult about leaks all make a difference. Some schools track their water use and hold contests to see which classroom can save the most. When millions of people take small steps, the water cycle has a better chance to keep California green."}],
    questions: [
      {q: "Why do people call the snowpack a frozen reservoir?", a: "It stores water as snow and releases it slowly as it melts", wrong: ["It is a lake that freezes every winter", "It is a giant tank of ice built by engineers"], type: "detail", mid: true},
      {q: "Which two main ideas does this text include?", a: "California depends on mountain snow for water, and people must conserve during droughts", wrong: ["Droughts never happen in California, and snow is not important", "Salmon live only in the ocean, and farms do not need water"], type: "main idea"},
      {q: "What is one effect of pumping too much water from underground?", a: "The ground can sink", wrong: ["The snowpack grows larger", "Rivers become colder"], type: "detail", evidence: "Even the ground can sink, because when people pump too much water from underground, the soil above it collapses like a squeezed sponge."},
      {q: "How is the section \"Moving Water to People\" organized?", a: "It states a problem and explains how people solved it", wrong: ["It compares two kinds of clouds", "It tells the events of one person's life"], type: "text feature", evidence: "To solve this, Californians built one of the largest water systems in the world."},
      {q: "What does \"conserve\" mean in this text?", a: "To use something carefully so it is not wasted", wrong: ["To pump water from underground", "To build a new dam"], type: "vocabulary"},
      {q: "Why might a warmer climate make droughts harder to handle?", a: "Less snow means less water is stored for the summer", wrong: ["Warmer air makes reservoirs larger", "Rain cannot fall in warm weather"], type: "inference", evidence: "That means the frozen reservoir will hold less water for summer."},
      {q: "Why does the author include the fact about the snowpack in two thousand fifteen?", a: "To show how severe the drought was", wrong: ["To explain how clouds form", "To prove that droughts help farms"], type: "author purpose"}]},
  {id: "g5-sally-ride", band: "5", lvl: 3, series: "True Stories", title: "Sally Ride: Reaching for the Stars", cover: "🚀", bg: "sky", kind: "informational",
    vocab: [["doctorate","the highest degree a university gives"], ["mission","an important trip or job with a goal"], ["investigated","looked closely to find out what happened"], ["influence","the power to change how others think or act"], ["tragedy","a very sad event"], ["encouraged","gave someone hope and support to do something"]],
    pages: [
      {heading: "A Curious Kid", icon: "👧", text: "Sally Ride was born in Los Angeles, California, in nineteen fifty one. As a girl, she was curious about everything, from how machines worked to what lay beyond the night sky. Her parents encouraged her to explore and ask questions. Sally loved science, but she also loved sports, and she became one of the best young tennis players in the country. She learned early that hard work and practice could take her far."},
      {heading: "Choosing Science", icon: "🔭", text: "Sally thought about becoming a professional tennis player, but science kept pulling her back. She studied at Stanford University, where she earned degrees in both physics and English. She loved how physics explained the hidden rules of the universe, from tiny atoms to faraway stars. She kept studying until she earned her doctorate, the highest degree a university gives, by researching how energy travels through the space between stars."},
      {heading: "An Unexpected Chance", icon: "📰", text: "In nineteen seventy seven, Sally was finishing her studies when she saw a newspaper announcement. NASA, the American space agency, was looking for new astronauts, and for the first time it was inviting women to apply. More than eight thousand people sent applications. After months of interviews, tests and medical exams, Sally was one of thirty five people chosen in nineteen seventy eight. Only six of them were women."},
      {heading: "Training Hard", icon: "🛰️", text: "Becoming an astronaut took years of training. Sally learned to fly jet planes, practiced emergency escapes and studied every system aboard the space shuttle. She also helped develop the shuttle's robotic arm, a long mechanical arm used to grab and release satellites. Some reporters asked her silly questions, such as whether she would cry if something went wrong. Sally answered patiently and kept her focus on the mission ahead."},
      {heading: "Making History", icon: "🚀", text: "On June eighteenth, nineteen eighty three, the space shuttle Challenger roared into the sky from Florida. Aboard was Sally Ride, the first American woman to travel into space. During the mission, which lasted six days, she used the robotic arm to release a satellite and then capture it again, something no one had done before with the shuttle's arm. Back home, crowds cheered and newspapers celebrated her historic flight."},
      {heading: "A Hard Time", icon: "🕯️", text: "Sally flew into space again in nineteen eighty four. She was training for a third mission when tragedy struck in nineteen eighty six: the Challenger shuttle broke apart shortly after launch, and all seven crew members were lost. Sally was chosen to serve on the group that investigated the accident. She worked hard to understand what had gone wrong so that future astronauts would be safer."},
      {heading: "Inspiring Young Scientists", icon: "🧪", text: "After leaving NASA, Sally became a professor of physics in California. She noticed that many girls loved science when they were young but lost interest as they grew older. In two thousand one, she started a company to change that. It created books, science festivals and programs that encouraged students, especially girls, to explore science, technology, engineering and math. She also wrote several science books for children."},
      {heading: "Her Lasting Gifts", icon: "⭐", text: "Sally Ride died in two thousand twelve, but her influence continues. A research ship and many schools carry her name, and the spot on the Moon where two NASA spacecraft ended their mission was named in her honor. The next year, she was awarded the Presidential Medal of Freedom, one of the highest honors in the country. Most of all, she showed young people that curiosity and hard work can open doors that once seemed closed."}],
    questions: [
      {q: "What did Sally see in nineteen seventy seven that changed her life?", a: "A newspaper notice that NASA wanted new astronauts, including women", wrong: ["A sign for a professional tennis contest", "A space shuttle launch in Florida"], type: "detail", mid: true},
      {q: "What is the main idea of this biography?", a: "Sally Ride became the first American woman in space and inspired others to study science", wrong: ["Sally Ride was the best tennis player in the world", "Sally Ride designed the first space shuttle by herself"], type: "main idea"},
      {q: "How is this biography organized?", a: "In time order, from her childhood to the end of her life", wrong: ["By comparing two different astronauts", "As a list of problems and solutions about rockets"], type: "text feature"},
      {q: "What can you infer from the questions some reporters asked Sally?", a: "Some people doubted that a woman could handle the job", wrong: ["Everyone was sure women made the best astronauts", "The reporters were experts on space travel"], type: "inference", evidence: "Some reporters asked her silly questions, such as whether she would cry if something went wrong."},
      {q: "Why did Sally start a company after leaving NASA?", a: "She wanted girls to stay interested in science as they grew up", wrong: ["She wanted to sell tennis equipment", "She wanted to build her own spacecraft"], type: "character", evidence: "She noticed that many girls loved science when they were young but lost interest as they grew older."},
      {q: "What does \"investigated\" mean in this biography?", a: "Looked closely to find out what happened", wrong: ["Celebrated with a party", "Flew into space a second time"], type: "vocabulary"},
      {q: "What is the author's point of view about Sally Ride?", a: "The author admires her and believes she made a lasting difference", wrong: ["The author thinks her work was not important", "The author believes she should have stayed a tennis player"], type: "point of view", evidence: "Most of all, she showed young people that curiosity and hard work can open doors that once seemed closed."}]},
  {id: "g5-wolves-return", band: "5", lvl: 4, series: "Big Ideas", title: "Wolves Return to California", cover: "🐺", bg: "grass", kind: "informational",
    vocab: [["livestock","farm animals such as cattle and sheep"], ["keystone species","an animal that has a big effect on its whole ecosystem"], ["ecosystem","all the living things in a place and how they depend on each other"], ["caution","to warn someone to be careful"], ["nonlethal","not meant to kill"], ["viewpoint","the way a person thinks about something"]],
    pages: [
      {heading: "A Surprise Visitor", icon: "🐺", text: "In December of two thousand eleven, a young gray wolf crossed from Oregon into Northern California. Scientists had fitted him with a tracking collar, and people later nicknamed him Journey. He was the first wild wolf known to enter the state in nearly ninety years. Since then, several wolf families, called packs, have settled in the northern part of the state, and Californians disagree about whether that is good news."},
      {heading: "Why Wolves Disappeared", icon: "📜", text: "Gray wolves once roamed across much of California. As settlers built ranches and towns in the eighteen hundreds and early nineteen hundreds, many people saw wolves as dangerous pests that threatened their livestock. Wolves were trapped, poisoned and hunted until none were left in the state. The last known wild wolf in California was killed in nineteen twenty four. For decades, the only wolves Californians saw were in zoos or in stories. Today, gray wolves are protected by law in California."},
      {heading: "Viewpoint One: Scientists", icon: "🔬", text: "Many wildlife biologists celebrate the return of the wolves. They explain that wolves are a keystone species, an animal that has a huge effect on its whole ecosystem. Some compare a wolf to the keystone at the top of a stone arch, the piece that holds all the others in place. Wolves hunt deer and elk, which keeps those herds from growing too large and eating too many young plants. Healthier plants then provide food and shelter for birds, insects and other animals. In this view, wolves help a damaged food web heal itself."},
      {heading: "An Example from Yellowstone", icon: "🌳", text: "Scientists often point to Yellowstone National Park as an example. Wolves were returned to the park in nineteen ninety five after being gone for about seventy years. Many researchers report that elk began moving more and lingering less along rivers, which gave willow trees a chance to grow back. Beavers then returned to build dams with the willows, creating ponds for fish and frogs. Other scientists caution that drought and other changes also played a role."},
      {heading: "Viewpoint Two: Ranchers", icon: "🐄", text: "Many ranchers see the situation differently. For a family that raises cattle in the mountains of Northern California, every calf matters, because the animals are how the family earns a living. Wolves sometimes attack cattle and sheep, and a single loss can cost a ranch thousands of dollars. Some ranchers also worry that wolves stress their herds, causing cows to lose weight even when no animal is killed. To them, wolves are not a symbol. They are a daily challenge."},
      {heading: "Searching for Common Ground", icon: "🤝", text: "Despite their differences, both groups want healthy land. Some ranchers now use nonlethal methods to protect their animals, such as guard dogs, bright flags on fences and riders who watch herds at night. The state of California has offered money to help pay for these tools and to make up for some lost livestock. Scientists track wolf collars and warn ranchers when a pack is nearby. Some ranchers say these steps help, while others say they cost too much time and money."},
      {heading: "What Do You Think?", icon: "🤔", text: "The return of the wolves raises a difficult question: how can people share the land with wild animals that both help and harm? A scientist and a rancher may look at the same wolf and see completely different things, one seeing balance and the other seeing risk. Both viewpoints come from real experiences and real evidence. Understanding each side is the first step toward finding solutions that work for wolves and people alike. As more packs settle in the state, these conversations will only grow more important."}],
    questions: [
      {q: "Why did wolves disappear from California long ago?", a: "People trapped, poisoned and hunted them", wrong: ["They moved to Oregon to find more food", "A long drought killed all their prey"], type: "detail", mid: true},
      {q: "What is the main idea of this text?", a: "The return of wolves brings both benefits and challenges, and people see it in different ways", wrong: ["Wolves are dangerous and should live only in zoos", "Yellowstone is the best national park in the country"], type: "main idea"},
      {q: "How do the scientists' and ranchers' viewpoints differ?", a: "Scientists focus on balance in the ecosystem, while ranchers focus on risks to their animals", wrong: ["Scientists want to remove all wolves, while ranchers want more wolves", "Both groups believe wolves have no effect at all"], type: "point of view", evidence: "A scientist and a rancher may look at the same wolf and see completely different things, one seeing balance and the other seeing risk."},
      {q: "According to many researchers, how did wolves help willow trees in Yellowstone?", a: "Elk spent less time eating plants near rivers", wrong: ["Wolves planted willow seeds as they traveled", "Wolves chased the beavers away from the trees"], type: "detail"},
      {q: "Why does the author include the sentence about other scientists who caution?", a: "To show that not all experts agree on what caused the changes", wrong: ["To prove that wolves harm rivers", "To explain how beavers build dams"], type: "author purpose", evidence: "Other scientists caution that drought and other changes also played a role."},
      {q: "What does \"keystone species\" mean in this text?", a: "An animal that has a big effect on its whole ecosystem", wrong: ["An animal that lives only among rocks", "An animal that is almost extinct"], type: "vocabulary"},
      {q: "How do the headings \"Viewpoint One\" and \"Viewpoint Two\" help readers?", a: "They show where each side's argument begins", wrong: ["They list the steps for training a wolf", "They tell the order of events in a wolf's life"], type: "text feature"}]},
  {id: "g5-bridge-challenge", band: "5", lvl: 5, series: "Voices", title: "Back to the Drawing Board", cover: "🌉", bg: "park", kind: "fiction",
    vocab: [["elegant","graceful and stylish"], ["nagged","kept bothering someone"], ["scattered","spread out in many places"], ["trusses","frames made of triangles that make a structure strong"], ["blueprint","a detailed plan for building something"], ["sleek","smooth and neat in shape"]],
    pages: [
      {icon: "🌉", text: "Lucía Torres had never earned anything less than a perfect score on a project, and she did not plan to start now. When Miss Patel announced the fifth grade bridge challenge, Lucía's mind was already racing. Each team would build a bridge from craft sticks and glue, and the bridge that held the most weight would win. Lucía and her partner, Marco Santos, had two weeks to design a winner."},
      {icon: "📐", text: "Lucía took charge immediately. She sketched a sleek, flat bridge with long, smooth beams, as elegant as a dancer stretching across a stage. Marco suggested adding triangles along the sides, the way he had seen on old railroad bridges, but Lucía shook her head. \"Triangles will make it look messy,\" she said. Marco shrugged and went along with her plan, although a small doubt nagged at him like a pebble in his shoe."},
      {icon: "🧱", text: "For ten days, they glued stick after stick, and the bridge grew longer and more beautiful. Classmates stopped to admire it. Lucía glowed with pride, certain that their bridge would take the blue ribbon. On test day, Miss Patel placed it between two desks and began hanging weights from the center. One weight held, then two, then three, and then came a sharp crack, and the bridge folded in the middle and crashed to the floor."},
      {icon: "😞", text: "The room went quiet. Lucía stared at the broken sticks scattered across the tiles, and she felt as if the floor had dropped out from under her. Other teams' bridges held five, eight, even twelve weights. That evening she refused to talk about it at dinner. She told herself that the challenge was silly and that she had never really cared, but the lump in her throat told a different story."},
      {icon: "👴", text: "The next day, Marco invited Lucía to his house, where his grandfather was fixing a broken chair on the porch. Lolo Ben had worked as an engineer on bridges in the Philippines for forty years. When Marco described what had happened, Lolo Ben laughed warmly. \"Every bridge I ever built stood on top of a hundred mistakes,\" he said. \"A failure is not the end of the road. It is a map that shows you where not to go.\""},
      {icon: "🔺", text: "Lolo Ben picked up a piece of the broken bridge and pressed on it. \"Long flat beams bend easily,\" he explained. \"But a triangle cannot change its shape unless one of its sides breaks. That is why engineers use them.\" Lucía glanced at Marco, remembering the idea she had brushed aside. Her cheeks burned. \"You were right about the triangles,\" she said quietly. \"I should have listened to you.\""},
      {icon: "🛠️", text: "Miss Patel allowed teams to rebuild for the spring open house, so Lucía and Marco went back to the drawing board. This time, they shared every decision. They tested small sections first, loading them until they snapped, and wrote down what each failure taught them. Their new bridge was covered in crisscrossing triangles, which Lolo Ben called trusses. It was not as sleek as the first one, but Lucía had stopped caring about sleek."},
      {icon: "🏅", text: "At the open house, the new bridge held twenty weights before it finally gave way. Another team still held the record, but Lucía did not mind. She was too busy explaining trusses to a crowd of curious parents. Later, she taped a single broken stick from the first bridge inside her notebook. Beside it she wrote a reminder to herself: the mistakes are part of the blueprint."}],
    questions: [
      {q: "Why did Lucía reject Marco's idea about triangles?", a: "She thought triangles would make the bridge look messy", wrong: ["She thought triangles were too hard to glue", "Miss Patel said triangles were not allowed"], type: "detail", mid: true},
      {q: "\"A small doubt nagged at him like a pebble in his shoe.\" What does this simile mean?", a: "Marco kept feeling a little worried about the plan", wrong: ["Marco had hurt his foot", "Marco was excited about the plan"], type: "vocabulary"},
      {q: "What does the idiom \"went back to the drawing board\" mean?", a: "They started planning again from the beginning", wrong: ["They gave up on the project", "They drew pictures instead of building"], type: "vocabulary"},
      {q: "The story is told in third person. How does the narrator show what Lucía feels after the bridge breaks?", a: "The narrator describes her private thoughts and the lump in her throat", wrong: ["Lucía tells the whole story in first person", "Marco explains her feelings in a letter"], type: "point of view", evidence: "She told herself that the challenge was silly and that she had never really cared, but the lump in her throat told a different story."},
      {q: "How does Lucía change during the story?", a: "She goes from insisting on her own perfect plan to sharing ideas and learning from mistakes", wrong: ["She goes from loving science to quitting it", "She goes from sharing ideas to working alone"], type: "character", evidence: "This time, they shared every decision."},
      {q: "What is the theme of this story?", a: "Mistakes can teach us how to succeed", wrong: ["The most beautiful things are always the strongest", "Winning first place is all that matters"], type: "theme", evidence: "Beside it she wrote a reminder to herself: the mistakes are part of the blueprint."},
      {q: "How was the second bridge different from the first bridge?", a: "It used triangles and was stronger, but it was less sleek", wrong: ["It was flatter and more elegant", "It was built without any glue"], type: "compare"}]},
  {id: "g5-telescopes", band: "5", lvl: 6, series: "Big Ideas", title: "From Galileo to Webb", cover: "🔭", bg: "sky", kind: "informational",
    vocab: [["transformed","changed completely"], ["astonished","greatly surprised"], ["atmosphere","the layer of air around Earth"], ["dismayed","upset and disappointed"], ["infrared","a kind of light people cannot see but can feel as heat"], ["reveals","shows something that was hidden"]],
    pages: [
      {heading: "Seeing Farther", icon: "🔭", text: "For most of human history, people could study the night sky only with their own eyes. They tracked the movements of the Moon, planets and stars with remarkable care, but anything too small or faint remained a mystery. That changed with an invention made of two pieces of curved glass inside a tube. Over four centuries, the telescope has transformed not only what we can see, but also what we believe about our place in the universe."},
      {heading: "Galileo Looks Up", icon: "🌙", text: "In sixteen oh nine, the Italian scientist Galileo Galilei heard about a Dutch invention that made distant objects appear closer. He built his own improved version and pointed it at the sky. What he saw astonished him. The Moon was not perfectly smooth, as many people believed, but covered with mountains and craters. Four small moons circled Jupiter, and the hazy Milky Way turned out to be countless individual stars."},
      {heading: "A Dangerous Idea", icon: "⚖️", text: "Galileo's discoveries supported a bold idea: that Earth and the other planets travel around the Sun. At the time, most people believed that Earth sat motionless at the center of everything. Galileo's observations challenged powerful leaders and beliefs held for centuries, and he was eventually ordered to stay inside his home for the rest of his life. Yet his evidence could not be ignored, and later scientists built on his work."},
      {heading: "Bigger Mirrors, Clearer Views", icon: "✨", text: "Over the next centuries, inventors learned that curved mirrors could gather light even better than glass lenses. Larger mirrors collected more light, which allowed astronomers to see fainter and more distant objects. Giant telescopes were built on mountaintops, such as Mount Wilson and Mount Palomar in California, where the air is thin and steady. Yet even these giants had a problem: Earth's atmosphere blurs and blocks some of the light from space."},
      {heading: "Hubble Above the Clouds", icon: "🛰️", text: "The solution was to put a telescope above the atmosphere. In nineteen ninety, the Hubble Space Telescope was launched into orbit around Earth. At first, scientists were dismayed: a tiny flaw in its main mirror made its pictures fuzzy. In nineteen ninety three, astronauts flew to Hubble and installed new optics, almost like giving it glasses. After the repair, Hubble sent back breathtaking images of faraway galaxies and helped scientists estimate the age of the universe."},
      {heading: "Webb Sees the Invisible", icon: "🌌", text: "In two thousand twenty one, a new telescope joined Hubble. The James Webb Space Telescope has a golden mirror made of eighteen pieces that unfolded in space like the petals of a flower. Unlike Hubble, which sees mostly visible light, Webb is designed to detect infrared light, a kind of light our eyes cannot see. Infrared light passes through clouds of dust, so Webb can peer at stars being born and at galaxies that formed long ago."},
      {heading: "Two Telescopes Compared", icon: "🔀", text: "Hubble and Webb are often called partners rather than rivals. Hubble circles Earth only a few hundred miles up, close enough that astronauts visited to repair and upgrade it five times. Webb orbits about a million miles away, far too distant for any repair crew. Webb's mirror is nearly three times as wide as Hubble's, so it collects far more light. Each telescope reveals details the other would miss, so scientists often study the same objects with both."},
      {heading: "Questions Without End", icon: "❓", text: "Every new telescope answers old questions and raises new ones. Galileo could only guess what lay beyond the stars he could see. Today, astronomers use Webb to study the air around planets that circle distant suns, searching for clues about whether any might support life. Telescopes are tools of glass and metal, but they are also windows for human curiosity. Whatever the next great telescope reveals, it will build on four hundred years of people daring to look up."}],
    questions: [
      {q: "What did Galileo discover when he looked at the Moon?", a: "It was covered with mountains and craters", wrong: ["It was perfectly smooth", "It had four small moons of its own"], type: "detail", mid: true},
      {q: "What is the main idea of this text?", a: "Better telescopes have changed what people know about the universe", wrong: ["Galileo invented every kind of telescope", "Telescopes work best in the middle of big cities"], type: "main idea"},
      {q: "Why did scientists put a telescope in space?", a: "Earth's atmosphere blurs and blocks light from space", wrong: ["There was no more room on mountaintops", "The telescope needed to be close to the Moon"], type: "detail", evidence: "Yet even these giants had a problem: Earth's atmosphere blurs and blocks some of the light from space."},
      {q: "Which statement correctly compares Hubble and Webb?", a: "Astronauts could repair Hubble, but Webb is too far away to repair", wrong: ["Webb is much closer to Earth than Hubble", "Both telescopes see only visible light"], type: "compare", evidence: "Webb orbits about a million miles away, far too distant for any repair crew."},
      {q: "The author calls telescopes \"windows for human curiosity.\" What does this metaphor mean?", a: "Telescopes let people explore and learn about things they wonder about", wrong: ["Telescopes are built from old windows", "Telescopes should always be kept indoors"], type: "vocabulary"},
      {q: "Why does the author include the section about Galileo's bold idea?", a: "To show that new evidence can challenge old beliefs, even when it is hard to accept", wrong: ["To explain how curved mirrors gather light", "To describe the golden mirror on Webb"], type: "author purpose", evidence: "Galileo's observations challenged powerful leaders and beliefs held for centuries, and he was eventually ordered to stay inside his home for the rest of his life."},
      {q: "How is most of this text organized?", a: "In time order, from Galileo's telescope to Webb", wrong: ["As a problem that was never solved", "By comparing telescopes with microscopes"], type: "text feature"}]}
];
